// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«המסע שלי»', () => {
  test('JR-05 Пустая קבלה — пустое состояние без «הסרת הקבלה» (подмена ответа) #31c88137 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: GET personal_commitments → [], прочие методы → abort (ничего не сохраняем).
    await page.route('**/rest/v1/personal_commitments**', async (route) => {
      if (route.request().method() === 'GET') {
        await route.fulfill({ json: [] });
      } else {
        await route.abort();
      }
    });

    // 2. Открыть `/journey`; дождаться исчезновения «טוענים את הקבלה האישית…».
    await page.goto('/journey');
    const card = page.getByRole('button', { name: /^מקבל על עצמי/ });
    await expect(card).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('טוענים את הקבלה האישית…')).toHaveCount(0, { timeout: 30_000 });
    await dismissMilestoneIfShown(page);
    await expect(page.getByText('עדיין לא הגדרת קבלה אישית.')).toBeVisible();

    // 3. Раскрыть «מקבל על עצמי».
    await card.click();
    const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
    await expect(field).toBeVisible();
    await expect(field).toHaveValue('');
    await expect(field).toHaveAttribute('placeholder', 'מה אני מקבל על עצמי');
    await expect(page.getByRole('button', { name: 'הסרת הקבלה' })).toHaveCount(0);
    await expect(page.getByText('הקבלה האישית לא נטענה')).toHaveCount(0);
  });
});
